export type BlogCategory = (typeof BLOG_CATEGORIES)[number]["slug"];
export type ArticleSection = { id: string; title: string; paragraphs: string[]; bullets?: string[]; code?: { language: string; value: string }; callout?: string };
export type Article = {
  slug: string; title: string; description: string; excerpt: string; category: BlogCategory;
  tags: string[]; published: string; updated: string; featured?: boolean; sections: ArticleSection[];
  faqs: { question: string; answer: string }[]; relatedService: string;
};

const published = "2026-09-27";

function editorialContext(topic: string) {
  if (/ISO 8583|STAN|RRN|PIN Data|Processing Code|POS Entry|Track 2|Currency Codes/i.test(topic)) return "the processor profile, message encoding, conditional-field rules, and transaction lifecycle";
  if (/payment|issuer|acquirer|authorization|HSM|reconciliation|financial/i.test(topic)) return "the financial state machine, ledger evidence, participant contract, and recovery procedure";
  if (/Laravel/i.test(topic)) return "the HTTP boundary, application service, queue or event flow, database transaction, and operational runtime";
  if (/Flutter/i.test(topic)) return "the widget boundary, domain model, local store, synchronization contract, and server authority";
  if (/Next.js|React/i.test(topic)) return "the server/client boundary, data contract, rendering path, browser runtime, and deployment edge";
  if (/Docker|Nginx|CI\/CD|GitHub Actions|Jenkins|AWS|Redis/i.test(topic)) return "the build artifact, runtime configuration, network boundary, persistent state, and operational recovery path";
  return "the domain boundary, data owner, integration contract, failure mode, and operating procedure";
}

function expandPoint(point: string, topic: string, index: number, compact: boolean) {
  const context = editorialContext(topic);
  const leads = [
    "Treat this as an explicit contract rather than an informal convention.",
    "The implementation should make this behavior visible in code and operations.",
    "This decision needs a named owner and a testable rule.",
    "A production design must define the normal path and the recovery path together.",
  ];
  const checks = [
    "Document accepted input, the authoritative source, emitted output, and the state recorded before control crosses a network boundary.",
    "Validate it at the first trusted boundary, preserve the evidence needed for investigation, and reject ambiguous state instead of guessing.",
    "Test the successful case alongside malformed input, duplicate delivery, timeout, partial completion, restart, and delayed response scenarios.",
    "Expose safe correlation identifiers, latency, outcome, and state transitions so support teams can diagnose a failure without accessing sensitive payloads.",
  ];
  const closing = compact
    ? "The network specification remains authoritative when a participant defines a different format or lifecycle."
    : `Review the effect across ${context}. A local shortcut is unsafe when it moves inconsistency into another service, a later retry, reconciliation, or a manual support process.`;
  return `${point}. ${leads[index % leads.length]} ${checks[index % checks.length]} ${closing}`;
}

function section(title: string, topic: string, points: string[], options: Partial<ArticleSection> = {}): ArticleSection {
  const id = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  const compact = topic.startsWith("ISO 8583 Explained:");
  return {
    id, title,
    paragraphs: [
      `${title} is a practical part of ${topic}, not an isolated implementation detail. A reliable design gives the concept a clear owner, defines the data it accepts, records each state change, and makes failures visible. The exact protocol or framework configuration may vary, but the engineering requirement remains the same: preserve intent and make the result explainable.`,
      `In production, the useful questions are where validation occurs, which system is authoritative, how a retry is recognized, and what operators can inspect after a timeout. Treating these questions as architecture decisions prevents accidental coupling and reduces the chance that a transient network failure becomes inconsistent business data.`,
      ...points.map((point, index) => expandPoint(point, topic, index, compact)),
    ],
    bullets: points,
    ...options,
  };
}

function makeArticle(input: Omit<Article, "published" | "updated" | "sections" | "faqs"> & { outline: [string, string[]][]; intro?: string; code?: ArticleSection["code"]; note?: string }): Article {
  const sections = input.outline.map(([title, points], index) => section(title, input.title, points, {
    ...(index === 0 && input.intro ? { paragraphs: [input.intro, `The sections below connect the concept to validation, state management, operations, and failure recovery. Examples are intentionally fictional and must be adapted to the contract published by the relevant framework, processor, or network.`] } : {}),
    ...(index === 1 && input.code ? { code: input.code } : {}),
    ...(index === input.outline.length - 1 && input.note ? { callout: input.note } : {}),
  }));
  return {
    ...input, published, updated: published, sections,
    faqs: [
      { question: `What is the main design concern in ${input.title.replace(/:.*$/, "")}?`, answer: `Correctness under normal and failure conditions. Define ownership, validate at the boundary, persist meaningful state, and make retries and operator investigation predictable.` },
      { question: "Should the examples be copied directly into production?", answer: "No. They illustrate architecture and must be adapted, reviewed, tested, and secured for the actual framework version, business rules, and integration contract." },
      { question: "How should teams test this design?", answer: "Combine unit tests for rules, integration tests for boundaries, and scenario tests for timeouts, duplicates, partial failure, recovery, and observability." },
    ],
  };
}

