for (const [slug,title,description,category,tags,relatedService,raw] of supporting) {
  definitions.push({ slug, title, description, excerpt: description, category, tags, relatedService,
    outline: raw.map(([heading, packed]) => [heading, packed.split("|")]) as [string,string[]][],
  });
}

export const ARTICLES: Article[] = definitions.map(makeArticle);
export const getArticle = (slug: string) => ARTICLES.find((article) => article.slug === slug);
export const getCategory = (slug: string) => BLOG_CATEGORIES.find((category) => category.slug === slug);
export const readingTime = (article: Article) => {
  const words = [article.title, article.excerpt, ...article.sections.flatMap((s) => [s.title, ...s.paragraphs, ...(s.bullets ?? [])]), ...article.faqs.flatMap((f) => [f.question, f.answer])].join(" ").split(/\s+/).length;
  return Math.max(4, Math.ceil(words / 210));
};
